// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ISapToken {
    function owner() external view returns (address);
    function renounceOwnership() external;
    function transferOwnership(address newOwner_) external;
}

contract SapToken is ISapToken {
    address private _owner;

    constructor() {
        _owner = msg.sender;
    }

    function owner() external view override returns (address) {
        return _owner;
    }

    function renounceOwnership() external override {
        require(msg.sender == _owner, "Only owner can renounce");
        _owner = address(0);
    }

    function transferOwnership(address newOwner_) external override {
        require(msg.sender == _owner, "Only owner can transfer");
        require(newOwner_ != address(0), "New owner cannot be zero address");
        _owner = newOwner_;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get the current owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Deploy a fresh SapToken contract locally
        SapToken sapToken = new SapToken();

        // The deployer (address(this)) should be the owner
        address deployer = address(this);
        address initialOwner = sapToken.owner();
        console.log("Deployer:", deployer);
        console.log("Initial owner:", initialOwner);
        assertEq(initialOwner, deployer, "Deployer should be the initial owner");

        // As the owner, renounce ownership
        sapToken.renounceOwnership();

        // Verify the owner is now address(0)
        address finalOwner = sapToken.owner();
        console.log("Final owner:", finalOwner);
        assertEq(finalOwner, address(0), "Owner should be address(0) after renounceOwnership");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

